<template>
  <academy-layout ref="layout" title="学习中心">
    <view v-if="loading" class="learning-skeleton"><view class="academy-skeleton" /><view class="academy-skeleton" /></view>
    <view v-else-if="error" class="academy-state"><text class="academy-state__title">学习内容加载失败</text><text class="academy-state__note">{{ error }}</text><view class="academy-button academy-button--secondary" @tap="load">重新加载</view></view>
    <template v-else>
      <view class="academy-metrics"><view class="academy-metric"><text class="academy-metric__value">{{ completedCount }}/{{ lessonCount }}</text><text class="academy-metric__label">已完成课程</text></view><view class="academy-metric"><text class="academy-metric__value">{{ overallProgress }}%</text><text class="academy-metric__label">总进度</text></view><view class="academy-metric"><text class="academy-metric__value">{{ learning.plan.dailyMinutes }}</text><text class="academy-metric__label">每日分钟</text></view></view>

      <view class="academy-section"><view class="academy-section__head"><view><text class="academy-section__title">学习计划</text><text class="academy-section__note">目标 {{ learning.plan.focus }}，计划日期 {{ learning.plan.targetDate }}</text></view><text class="academy-link" @tap="showPlan = !showPlan">{{ showPlan ? '收起' : '调整计划' }}</text></view><view v-if="showPlan" class="academy-panel"><view class="form-grid"><view class="academy-field"><text class="academy-label">每日学习时间</text><picker :range="dailyOptions" @change="planDraft.dailyMinutes = dailyOptions[Number($event.detail.value)]"><view class="academy-select">{{ planDraft.dailyMinutes }} 分钟</view></picker></view><view class="academy-field"><text class="academy-label">目标等级</text><picker :range="focusOptions" @change="planDraft.focus = focusOptions[Number($event.detail.value)]"><view class="academy-select">{{ planDraft.focus }}</view></picker></view></view><view class="academy-field"><text class="academy-label">计划完成日期</text><picker mode="date" :value="planDraft.targetDate" @change="planDraft.targetDate = $event.detail.value"><view class="academy-select">{{ planDraft.targetDate }}</view></picker></view><view class="academy-button" @tap="savePlan">保存计划</view></view></view>

      <view v-if="activeLesson" class="academy-section"><view class="academy-section__head"><view><text class="academy-section__title">正在学习</text><text class="academy-section__note">{{ activeLesson.chapterTitle }} / {{ activeLesson.title }}</text></view><text class="academy-link" @tap="activeLesson = null">关闭</text></view><view class="lesson-player academy-panel">
        <video v-if="activeLesson.videoUrl" class="lesson-video" :src="activeLesson.videoUrl" controls :initial-time="lessonPosition(activeLesson.id)" @timeupdate="handleTimeUpdate" @ended="completeLesson" />
        <view v-else class="lesson-fallback"><image src="/static/images/lowair-learning-video.png" mode="aspectFill" /><view class="lesson-fallback__overlay"><text>{{ activeLesson.type === 'video' ? '课程视频待后端媒体地址接入' : '图文与情景课程' }}</text><view class="academy-button academy-button--small" @tap="advanceLesson">学习 5 分钟</view></view></view>
        <view class="player-info"><view><text class="academy-row__title">{{ activeLesson.title }}</text><text class="academy-row__note">{{ activeLesson.duration }} 分钟 · {{ typeLabel(activeLesson.type) }}</text></view><text class="academy-tag academy-tag--accent">{{ lessonProgress(activeLesson.id) }}%</text></view><view class="academy-progress"><view class="academy-progress__value" :style="{ width: lessonProgress(activeLesson.id) + '%' }" /></view><text class="academy-source">内容来源：{{ activeLesson.source }}</text><view class="academy-actions player-actions"><view class="academy-button academy-button--secondary academy-button--small" @tap="addWrongPractice">去错题练习</view><view class="academy-button academy-button--small" @tap="completeLesson">标记完成</view></view>
      </view></view>

      <view class="academy-section"><view class="academy-section__head"><view><text class="academy-section__title">课程章节</text><text class="academy-section__note">视频进度与章节完成状态会自动保存</text></view></view><view class="chapter-list"><view v-for="chapter in curriculum" :key="chapter.id" class="chapter-card"><view class="chapter-head" @tap="toggleChapter(chapter.id)"><view><text class="chapter-title">{{ chapter.title }}</text><text class="academy-section__note">{{ chapter.note }}</text></view><text class="academy-link">{{ expanded[chapter.id] ? '收起' : '展开' }}</text></view><view v-if="expanded[chapter.id]" class="lesson-list"><view v-for="lesson in chapter.lessons" :key="lesson.id" class="lesson-row" @tap="openLesson(lesson, chapter)"><view class="lesson-type">{{ typeGlyph(lesson.type) }}</view><view class="academy-row__main"><text class="academy-row__title">{{ lesson.title }}</text><text class="academy-row__note">{{ typeLabel(lesson.type) }} · {{ lesson.duration }} 分钟</text><view class="academy-progress lesson-progress"><view class="academy-progress__value" :style="{ width: lessonProgress(lesson.id) + '%' }" /></view></view><text class="lesson-percent">{{ lessonProgress(lesson.id) }}%</text></view></view></view></view></view>

      <view class="academy-section"><view class="academy-row" @tap="go('/pages/academy/exam?mode=practice')"><view class="academy-row__main"><text class="academy-row__title">章节练习与错题巩固</text><text class="academy-row__note">按题型练习，错题会写入学习档案</text></view><text class="academy-link">开始练习 ›</text></view></view>
    </template>
  </academy-layout>
</template>

<script>
import AcademyLayout from './AcademyLayout.vue'
import { academyService } from '../services'
export default {
  name: 'LearningPage', components: { AcademyLayout },
  data() { return { loading: true, error: '', curriculum: [], learning: { progress: {}, videoPosition: {}, plan: { dailyMinutes: 30, targetDate: '', focus: '超视距' } }, expanded: { 'chapter-01': true }, activeLesson: null, showPlan: false, planDraft: {}, dailyOptions: [15, 20, 30, 45, 60], focusOptions: ['视距内', '超视距', '教员'], lastVideoSave: 0 } },
  computed: { lessons() { return this.curriculum.flatMap((chapter) => chapter.lessons) }, lessonCount() { return this.lessons.length }, completedCount() { return this.lessons.filter((lesson) => this.lessonProgress(lesson.id) >= 100).length }, overallProgress() { return this.lessonCount ? Math.round(this.lessons.reduce((sum, lesson) => sum + this.lessonProgress(lesson.id), 0) / this.lessonCount) : 0 } },
  mounted() { this.load() },
  methods: {
    async load() { this.loading = true; this.error = ''; try { const [curriculum, learning] = await Promise.all([academyService.getCurriculum(), academyService.getLearningState()]); this.curriculum = curriculum; this.learning = learning; this.planDraft = { ...learning.plan } } catch (error) { this.error = error.message } finally { this.loading = false } },
    lessonProgress(id) { return Number(this.learning.progress[id]) || 0 }, lessonPosition(id) { return Number(this.learning.videoPosition[id]) || 0 },
    toggleChapter(id) { this.expanded[id] = !this.expanded[id] },
    openLesson(lesson, chapter) { this.activeLesson = { ...lesson, chapterTitle: chapter.title }; this.$nextTick(() => this.$refs.layout.showToast(this.lessonProgress(lesson.id) ? `已恢复到 ${this.lessonProgress(lesson.id)}%` : '已开始本节课程')) },
    typeLabel(type) { return { video: '视频', article: '图文', simulator: '情景模拟' }[type] || type }, typeGlyph(type) { return { video: '播', article: '读', simulator: '练' }[type] || '课' },
    async advanceLesson() { const progress = Math.min(95, this.lessonProgress(this.activeLesson.id) + Math.max(8, Math.round(500 / this.activeLesson.duration))); await this.persistLesson(progress, this.lessonPosition(this.activeLesson.id) + 300); this.$refs.layout.showToast('学习进度已保存') },
    async completeLesson() { if (!this.activeLesson) return; await this.persistLesson(100, this.activeLesson.duration * 60); this.$refs.layout.showToast('本节已完成，学习档案已更新') },
    async persistLesson(progress, position) { await academyService.updateLessonProgress(this.activeLesson.id, progress, position); this.learning.progress[this.activeLesson.id] = progress; this.learning.videoPosition[this.activeLesson.id] = position },
    handleTimeUpdate(event) { const now = Date.now(); if (now - this.lastVideoSave < 5000 || !this.activeLesson) return; this.lastVideoSave = now; const current = Number(event.detail.currentTime) || 0; const duration = Number(event.detail.duration) || this.activeLesson.duration * 60; this.persistLesson(Math.min(99, Math.round(current / duration * 100)), current) },
    async savePlan() { try { this.learning.plan = await academyService.updateLearningPlan(this.planDraft); this.showPlan = false; this.$refs.layout.showToast('学习计划已保存') } catch (error) { this.$refs.layout.showToast(error.message) } },
    addWrongPractice() { this.go('/pages/academy/exam?mode=practice&type=wrong') }, go(url) { uni.navigateTo({ url }) }
  }
}
</script>

<style scoped>
.learning-skeleton { display: flex; flex-direction: column; gap: 18rpx; }.form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12rpx; }.lesson-fallback { position: relative; overflow: hidden; height: 330rpx; border-radius: 10rpx; }.lesson-fallback image { width: 100%; height: 100%; }.lesson-fallback__overlay { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 22rpx; padding: 30rpx; background: rgba(3,20,31,.68); color: #edf7f8; font-size: 23rpx; text-align: center; }.lesson-video { width: 100%; height: 330rpx; border-radius: 10rpx; }.player-info { display: flex; align-items: center; justify-content: space-between; gap: 18rpx; margin: 20rpx 0 14rpx; }.player-actions { justify-content: flex-end; margin-top: 18rpx; }.chapter-list { display: flex; flex-direction: column; gap: 14rpx; }.chapter-card { overflow: hidden; border: 1rpx solid var(--line); border-radius: 14rpx; background: var(--surface); }.chapter-head { display: flex; align-items: center; justify-content: space-between; gap: 20rpx; padding: 20rpx; }.chapter-title { display: block; color: var(--text); font-size: 27rpx; font-weight: 720; }.lesson-list { border-top: 1rpx solid var(--line); }.lesson-row { display: flex; align-items: center; gap: 14rpx; padding: 18rpx 20rpx; }.lesson-row + .lesson-row { border-top: 1rpx solid var(--line); }.lesson-type { flex: 0 0 auto; display: flex; width: 48rpx; height: 48rpx; align-items: center; justify-content: center; border-radius: 9rpx; background: var(--surface-strong); color: var(--accent); font-size: 20rpx; font-weight: 700; }.lesson-progress { margin-top: 8rpx; }.lesson-percent { flex: 0 0 auto; color: var(--muted); font-size: 20rpx; }
</style>
